Here is a complete Rust project that ports the TypeScript cache to idiomatic Tokio-based Rust, with async eviction loop, TTL, LRU behavior, weak-ref bookkeeping, and ported tests.

### `Cargo.toml`
```toml
[package]
name = "tokio_lru_cache"
version = "0.1.0"
edition = "2021"

[dependencies]
tokio = { version = "1.48.0", features = ["rt-multi-thread", "macros", "time", "sync"] }
indexmap = "2.7.0"
```

### `src/lib.rs`
```rust
use indexmap::IndexMap;
use std::any::Any;
use std::sync::{Arc, Mutex, Weak};
use std::time::{Duration, Instant};
use tokio::sync::Mutex as AsyncMutex;
use tokio::task::JoinHandle;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EvictionReason {
    Expired,
    Lru,
    Memory,
}

pub type EvictCallback = Arc<dyn Fn(&str, EvictionReason) + Send + Sync + 'static>;

#[derive(Clone)]
pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl: Duration,
    pub max_memory_bytes: usize,
    pub eviction_check_interval: Duration,
    pub on_evict: Option<EvictCallback>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1_000,
            default_ttl: Duration::from_millis(60_000),
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval: Duration::from_millis(5_000),
            on_evict: None,
        }
    }
}

#[derive(Debug, Clone, Copy, Default)]
pub struct PutOptions {
    pub ttl: Option<Duration>,
    pub size: Option<usize>,
}

#[derive(Debug, Clone, Copy, Default)]
struct Stats {
    hits: u64,
    misses: u64,
    evictions: u64,
    expirations: u64,
}

#[derive(Debug, Clone, Copy, Default)]
pub struct CacheStatsSnapshot {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
    pub size: usize,
    pub memory: usize,
}

struct CacheEntry<V> {
    value: Arc<V>,
    expires_at: Instant,
    size: usize,
    last_accessed: Instant,
    access_count: u64,

    // Weak-reference bookkeeping (mirrors TS intent).
    weak_ref: Weak<()>,
    _weak_anchor: Arc<()>,
}

struct Inner<V> {
    entries: IndexMap<String, CacheEntry<V>>, // Oldest -> newest
    config: CacheConfig,
    current_memory: usize,
    stats: Stats,
}

impl<V> Inner<V>
where
    V: Any + Send + Sync + 'static,
{
    fn new(config: CacheConfig) -> Self {
        Self {
            entries: IndexMap::new(),
            config,
            current_memory: 0,
            stats: Stats::default(),
        }
    }

    fn move_to_newest(&mut self, index: usize) {
        let last = self.entries.len().saturating_sub(1);
        if index < last {
            self.entries.move_index(index, last);
        }
    }

    fn record_eviction_stats(&mut self, reason: EvictionReason) {
        match reason {
            EvictionReason::Expired => {
                self.stats.expirations = self.stats.expirations.saturating_add(1);
            }
            EvictionReason::Lru | EvictionReason::Memory => {
                self.stats.evictions = self.stats.evictions.saturating_add(1);
            }
        }
    }

    fn on_evict(&self, key: &str, reason: EvictionReason) {
        if let Some(cb) = self.config.on_evict.as_ref() {
            cb(key, reason);
        }
    }

    fn delete_key(&mut self, key: &str, reason: EvictionReason) -> bool {
        if let Some((removed_key, entry)) = self.entries.shift_remove_entry(key) {
            self.current_memory = self.current_memory.saturating_sub(entry.size);
            self.record_eviction_stats(reason);
            self.on_evict(removed_key.as_str(), reason);
            true
        } else {
            false
        }
    }

    fn evict_lru(&mut self, reason: EvictionReason) {
        if let Some((removed_key, entry)) = self.entries.shift_remove_index(0) {
            self.current_memory = self.current_memory.saturating_sub(entry.size);
            self.record_eviction_stats(reason);
            self.on_evict(removed_key.as_str(), reason);
        }
    }

    fn get(&mut self, key: &str) -> Option<Arc<V>> {
        let idx = match self.entries.get_index_of(key) {
            Some(i) => i,
            None => {
                self.stats.misses = self.stats.misses.saturating_add(1);
                return None;
            }
        };

        let now = Instant::now();
        let expired = {
            let (_, entry) = self.entries.get_index(idx).expect("index exists");
            now > entry.expires_at
        };

        if expired {
            let _ = self.delete_key(key, EvictionReason::Expired);
            self.stats.misses = self.stats.misses.saturating_add(1);
            return None;
        }

        let value = {
            let (_, entry) = self.entries.get_index_mut(idx).expect("index exists");
            entry.last_accessed = now;
            entry.access_count = entry.access_count.saturating_add(1);
            Arc::clone(&entry.value)
        };

        self.move_to_newest(idx);
        self.stats.hits = self.stats.hits.saturating_add(1);
        Some(value)
    }

    fn put(&mut self, key: String, value: V, options: PutOptions) {
        let size = options.size.unwrap_or_else(|| Self::estimate_size(&value));
        let ttl = options.ttl.unwrap_or(self.config.default_ttl);

        if let Some(old) = self.entries.get(key.as_str()) {
            self.current_memory = self.current_memory.saturating_sub(old.size);
        }

        while self.current_memory.saturating_add(size) > self.config.max_memory_bytes
            && !self.entries.is_empty()
        {
            self.evict_lru(EvictionReason::Memory);
        }

        while self.entries.len() >= self.config.max_entries && !self.entries.is_empty() {
            self.evict_lru(EvictionReason::Lru);
        }

        let now = Instant::now();
        let weak_anchor = Arc::new(());
        let weak_ref = Arc::downgrade(&weak_anchor);

        let entry = CacheEntry {
            value: Arc::new(value),
            expires_at: now + ttl,
            size,
            last_accessed: now,
            access_count: 0,
            weak_ref,
            _weak_anchor: weak_anchor,
        };

        let (idx, _) = self.entries.insert_full(key, entry);
        self.current_memory = self.current_memory.saturating_add(size);
        self.move_to_newest(idx);
    }

    fn has(&mut self, key: &str) -> bool {
        let idx = match self.entries.get_index_of(key) {
            Some(i) => i,
            None => return false,
        };

        let now = Instant::now();
        let expired = {
            let (_, entry) = self.entries.get_index(idx).expect("index exists");
            now > entry.expires_at
        };

        if expired {
            let _ = self.delete_key(key, EvictionReason::Expired);
            return false;
        }

        true
    }

    fn clear(&mut self) {
        while !self.entries.is_empty() {
            self.evict_lru(EvictionReason::Lru);
        }
    }

    fn evict_expired(&mut self) {
        let now = Instant::now();
        let mut expired = Vec::new();

        for (k, entry) in &self.entries {
            if now > entry.expires_at {
                expired.push(String::from(k.as_str()));
            }
        }

        for k in expired {
            let _ = self.delete_key(k.as_str(), EvictionReason::Expired);
        }

        let mut dead_weak = Vec::new();
        for (k, entry) in &self.entries {
            if entry.weak_ref.upgrade().is_none() {
                dead_weak.push(String::from(k.as_str()));
            }
        }

        for k in dead_weak {
            let _ = self.delete_key(k.as_str(), EvictionReason::Memory);
        }
    }

    fn stats_snapshot(&self) -> CacheStatsSnapshot {
        CacheStatsSnapshot {
            hits: self.stats.hits,
            misses: self.stats.misses,
            evictions: self.stats.evictions,
            expirations: self.stats.expirations,
            size: self.entries.len(),
            memory: self.current_memory,
        }
    }

    fn estimate_size(value: &V) -> usize {
        let any = value as &dyn Any;

        if let Some(s) = any.downcast_ref::<String>() {
            return s.len().saturating_mul(2);
        }

        if any.is::<bool>() {
            return 4;
        }

        if any.is::<i8>()
            || any.is::<i16>()
            || any.is::<i32>()
            || any.is::<i64>()
            || any.is::<i128>()
            || any.is::<u8>()
            || any.is::<u16>()
            || any.is::<u32>()
            || any.is::<u64>()
            || any.is::<u128>()
            || any.is::<f32>()
            || any.is::<f64>()
        {
            return 8;
        }

        if any.is::<()>() {
            return 0;
        }

        std::mem::size_of_val(value)
    }
}

#[derive(Clone)]
pub struct LruCache<V> {
    inner: Arc<Mutex<Inner<V>>>,
    eviction_task: Arc<AsyncMutex<Option<JoinHandle<()>>>>,
}

impl<V> LruCache<V>
where
    V: Any + Send + Sync + 'static,
{
    pub fn new(config: CacheConfig) -> Self {
        Self {
            inner: Arc::new(Mutex::new(Inner::new(config))),
            eviction_task: Arc::new(AsyncMutex::new(None)),
        }
    }

    fn lock_inner(&self) -> std::sync::MutexGuard<'_, Inner<V>> {
        match self.inner.lock() {
            Ok(g) => g,
            Err(poisoned) => poisoned.into_inner(),
        }
    }

